import { ApolloServerPluginDrainHttpServer } from '@apollo/server/plugin/drainHttpServer';
import cors from 'cors';
import http from 'node:http';
import express from 'express';
import { ApolloServer } from '@apollo/server';
import { buildSubgraphSchema } from '@apollo/subgraph';
import { expressMiddleware } from '@as-integrations/express5';
import type { BackendServer, BackendContext } from './backend-server.js';
import { DefaultRESTRoute } from './rest-route.js';

export type DefaultServerOptions = {
  /**
   * name of the backend server.
   */
  name: string;

  /**
   * routes to load.
   */
  routes?: DefaultRESTRoute,

  /**
   * enables cors.
   */
  cors?: boolean;
};

export class DefaultServer implements BackendServer {
  // name = 'symphony-server';

  async run({ name, ...context }: BackendContext) {
    const port = context.port || 3000;
    const app = express();
    const httpServer = http.createServer(app);
    
    context.middlewares?.forEach((middleware) => {
      app.use(middleware);
    });

    // The ApolloServer constructor requires two parameters: your schema
    // definition and your set of resolvers.
    if (context.gql?.typeDefs) {
      const server = new ApolloServer({
        schema: buildSubgraphSchema([{
          typeDefs: context.gql?.typeDefs,
          resolvers: context.gql?.resolvers
        }]),
        plugins: [ApolloServerPluginDrainHttpServer({ httpServer })],
        logger: { debug: () => {}, info: () => {}, warn: console.warn, error: console.error },
        stopOnTerminationSignals: false,
      });

      await server.start();

      app.use(cors<cors.CorsRequest>({
        origin(origin, callback) {
          callback(null, true);
        },
        credentials: true,
      }));
      
      app.use(
        '/graphql',
        express.json(),
        // expressMiddleware accepts the same arguments:
        // an Apollo Server instance and optional configuration options
        expressMiddleware(server, {
          context: async ({ req }) => req,
        }),
      );
    }

    app.use(cors<cors.CorsRequest>({
      origin(origin, callback) {
        callback(null, true);
      },
      credentials: true,
    }));

    context.middlewares?.forEach((middleware) => {
      app.use(middleware);
    });
    
    context.routes?.forEach((route) => {
      const method = route.method || 'get';
      app[method](route.path, route.route);
    });

    await new Promise<void>((resolve) => httpServer.listen({ port }, resolve));

    return {
      appName: name,
      port,
      url: `http://localhost:${port}`,
      stop: async () => {
        httpServer.closeAllConnections();
        httpServer.close();
      }
    }
  }
}
